namespace HagiCode.Libs.Providers.Tests;

// Real pi 1.2.0 --mode rpc captures (sanitized: session id, dialog ids and tool call ids replaced by stable fixtures; the
// model and provider renamed to mock-model/mock; system-prompt messages cut out of the stream and out of agent_end; system
// paths removed). Captured 2026-10-13 through a stdin/stdout harness against the bundled ask-user-question extension, one
// haiku call per full run.
//
// Findings recorded for openspec change add-pi-interactive-user-questions (tasks 1.1, 1.2 and 11.1 to 11.4):
//  * get_state answers { id, type: "response", command: "get_state", success: true, data } and data.sessionId is the session id
//    (data.sessionFile only when a session is persisted). RPC mode writes no session header, and data has no cwd or timestamp.
//  * The command reply carries the command id. A prompt that starts a run answers data.disposition "started". A prompt that an
//    extension command consumed answers "handled" and no run starts, so no agent_settled follows.
//  * A rejected prompt answers success false with an error text (missing message, no API key for the provider). No run starts
//    and no agent_settled follows. A model failure after acceptance is not a rejection: the run reports an assistant message
//    with stopReason error and errorMessage, then agent_end and agent_settled.
//  * Order at the end of a run: turn_end, agent_end (willRetry false), agent_settled { aborted }. The process keeps running
//    until its standard input is closed and then exits 0 within a few milliseconds.
//  * The question dialog (extension_ui_request, method input) arrives between tool_execution_start and tool_execution_end of
//    its tool call. The tool call id inside the dialog title equals the toolCallId of the surrounding tool events.
//  * abort answers { type: "response", command: "abort", success: true } AFTER the agent_settled { aborted: true } it caused.
//    The bundled extension passes the abort signal to its dialog, so an aborted run ends the open dialog by itself (the tool
//    result says the user declined); a host that answers the dialog first gets the same events.
//  * Pi ignores an extension_ui_response whose dialog is not open any more.
//  * Two extensions that register the same tool name make pi exit with code 1 during startup, before any protocol record:
//    stdout stays empty and stderr says: Error: Failed to load extension "<path>": Tool "ask_user_question" conflicts with
//    <path of the extension that registered it first>. The order of the two -e options does not matter.
//  * A user extension's dialogs (select, confirm, editor, input) block on a response like the question dialog does; notify,
//    setStatus, setWidget, setTitle and set_editor_text are fire-and-forget. A cancelled response resolves select, input and
//    editor to undefined and confirm to false.
//  * Transport: a dialog title of 4 MB (a 9 MB line, with U+2028 inside the JSON string) arrived intact and a 700 KB answer
//    value went back intact.
//
// Findings recorded for openspec change pi-run-steering (tasks 1.1 to 1.3). Captured 2026-10-26 with pi 1.2.0 --mode rpc, no
// extensions, one haiku call per run through a local OpenAI-compatible gateway, under a throwaway --session-dir. Fixtures:
// Fixtures/Pi/steer-*.jsonl (stdout only; the steer inputs are described below). Model, response ids, session id and paths are
// replaced as in the captures above. The steer inputs are: (a) steer during a bash tool call, (b) steer during text
// streaming, (c) two steers with identical text during a tool call, (d) steer written right after agent_end, (e) an empty
// message, (f) a steer without a message key and a steer with a numeric message.
//  * Reply: { id: "hagicode-steer-<n>", type: "response", command: "steer", success: true, data: { disposition: "queued" } }.
//    It carries the command id only. Latency was 3 ms mid-run and about 30 ms at run start (both within the same read batch).
//  * Injection (D3): a user message_start whose content is one text block with exactly the steer text. It arrives at the start
//    of the next turn, after the turn_end of the turn that ran the tool or streamed the text, and before the next model call.
//    Pi delivers one steer per turn (steeringMode one-at-a-time): with two steers queued, two turns follow, one per steer.
//  * queue_update { steering: [...] } follows each queue change, but its drop is not a reliable signal: in one capture the
//    removal came right before the injection, in another only after it. The message_start text is the signal the provider uses.
//  * A steer is accepted mid tool call (a) and mid text stream (b) alike. It is consumed at the turn boundary, never inside the
//    turn that was running.
//  * Identical texts (c): both steers are queued (two queue_update lines) and injected in order, one per turn. Matching the
//    oldest pending text FIFO resolves them correctly.
//  * Empty message (e): the reply is success true with disposition queued, and the empty text is injected as a real user turn
//    that costs a model call. The provider must refuse an empty or whitespace message itself and never write it.
//  * Missing or non-string message (f): success false, nothing queued, no injection. Error texts:
//    "Cannot read properties of undefined (reading 'startsWith')" (no message key) and "text.startsWith is not a function"
//    (numeric message). Pi reports a bad steer on the same response shape it uses for prompts.
//  * Steer written at agent_end (d): no reply, no injection. agent_settled followed in the same millisecond and pi exited 0. A
//    steer that arrives after agent_end is not processed, so the provider closes its accepting window at agent_end.
//  * Pending steers at settle: in every capture, every queued steer was injected before agent_end. Nothing in the captures
//    shows Pi continuing a queued steer after agent_settled. Design D4 therefore resolves a still-pending steer at agent_settled
//    as NotConsumed at once and uses no settle wait.
//  * End-to-end check (task 5.2, same day): the real pi through PiProvider and the shared CliProcessManager (memory-cap launch
//    path included), throwaway session directory, one tool call per run. (a) one steer: steer-1 Sent, then steer-1 Consumed.
//    (c) two identical steers: steer-1 Sent and steer-2 Sent, then steer-1 Consumed and steer-2 Consumed, one outcome each.
//    The event types of the run were session.started, tool.call, tool.update, tool.completed, assistant, terminal.completed.
internal static class PiRpcCapture
{
    public static IReadOnlyList<string> Lines(string jsonLines)
    {
        return jsonLines.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
    }

    /// <summary>The standard error of pi 1.2.0 when a user extension registers ask_user_question as well. Standard output stays empty and the exit code is 1.</summary>
    public const string QuestionToolConflictStandardError =
        "Error: Failed to load extension \"/path/to/user-extension/ask-user-question.ts\": Tool \"ask_user_question\" conflicts with /path/to/bundled/ask-user-question.ts\n" +
        "Hint: Start without extensions using \"pi -ne\".\n";

    /// <summary>The reply to the get_state command (pi 1.2.0, started with --no-session). The session id is data.sessionId; there is no sessionFile with --no-session, and no cwd, timestamp or header version. Lines pi wrote to stdout, in order.</summary>
    public static IReadOnlyList<string> GetStateReply => Lines("""
{"id":"hagicode-get-state","type":"response","command":"get_state","success":true,"data":{"model":{"id":"mock-model","name":"Mock model","api":"openai-completions","provider":"mock","baseUrl":"http://127.0.0.1:1/v1","reasoning":true,"input":["text"],"cost":{"input":0,"output":0,"cacheRead":0,"cacheWrite":0},"contextWindow":200000,"maxTokens":32000,"compat":{"supportsDeveloperRole":false}},"thinkingLevel":"medium","isStreaming":false,"isCompacting":false,"steeringMode":"one-at-a-time","followUpMode":"one-at-a-time","sessionId":"pi-session-fixture","autoCompactionEnabled":true,"messageCount":0,"pendingMessageCount":0}}
""");

    /// <summary>The reply to a prompt command without a message: success false and the error text, no run starts, no agent_settled follows. Lines pi wrote to stdout, in order.</summary>
    public static IReadOnlyList<string> PromptRejectedMissingMessage => Lines("""
{"id":"hagicode-prompt","type":"response","command":"prompt","success":false,"error":"Cannot read properties of undefined (reading 'startsWith')"}
""");

